const photo='https://images.unsplash.com/photo-1585747860715-2ba37e788b70?auto=format&fit=crop&w=1600&q=85';
const brand='<span class="mark" aria-hidden="true">✓</span>streetvouch';
const app=document.getElementById('app');
const barber=location.pathname.startsWith('/t/JB001');
function modal(title,copy){const d=document.createElement('dialog');d.className='dialog';const h=document.createElement('h2');h.textContent=title;const p=document.createElement('p');p.textContent=copy;const close=document.createElement('button');close.className='btn';close.textContent='Got it';close.onclick=()=>d.close();d.append(h,p,close);document.body.append(d);d.addEventListener('close',()=>d.remove());d.addEventListener('click',e=>{if(e.target===d)d.close()});d.showModal();}
function home(){app.innerHTML=`<header class="wrap"><nav class="nav" aria-label="Main navigation"><a class="brand" href="/" aria-label="StreetVouch home">${brand}</a><div class="navlinks"><a href="#benefits">Why StreetVouch</a><a href="#how">How it works</a><a href="#questions">Questions</a></div><a class="btn" href="/t/JB001/">Try the experience <span aria-hidden="true">↗</span></a></nav></header>
<main><section class="hero"><div class="wrap hero-grid"><div class="reveal"><div class="eyebrow">For the good businesses on your street</div><h1>You take care<br>of customers.<br><span>We take care<br>of the feedback.</span></h1><p>More honest reviews. Thoughtful replies. Customer insights you can actually use. All starting with one simple tap.</p><div class="actions"><a class="btn" href="/t/JB001/">Explore the barber demo <span aria-hidden="true">↗</span></a><a class="btn light" href="#how">How it works</a></div><div class="micro">Built for independent businesses. Designed around your day.</div></div><div class="hero-art reveal"><img class="hero-photo" src="${photo}" alt="Warmly lit independent barbershop with leather chairs and brick walls" fetchpriority="high"><span class="photo-label">Small business. Big reputation.</span><div class="review-card"><div class="card-top"><strong>A little feedback. A lot of value.</strong><span class="stars" aria-label="5 stars">★★★★★</span></div><p>“Great cut, a warm welcome and a team that really listens.”</p><div class="reply-label">✓ Thoughtful reply, handled for you</div><small class="micro">Illustrative review</small></div><span class="vertical-caption">Made for your kind of business.</span></div></div></section>
<div class="strip"><div class="wrap"><strong>Local by nature.</strong><span>Barbers & salons</span><span>Cafés & restaurants</span><span>Independent shops</span><span>Local services</span></div></div>
<section class="story-section" aria-labelledby="story-title"><div class="wrap"><div class="story-heading"><div><div class="eyebrow">One tap. The full picture.</div><h2 id="story-title">See a visit become<br>a useful decision.</h2></div><p>Follow a customer’s feedback from the counter to insight, action and a calmer week.</p></div><div class="story-demo"><div class="story-track" aria-hidden="true"><span class="story-line"></span><span class="story-dot d1"></span><span class="story-dot d2"></span><span class="story-dot d3"></span><span class="story-dot d4"></span></div><article class="story-stage tap-stage"><span class="stage-no">01</span><div class="tap-scene"><div class="tag-card"><span class="tag-logo">✓</span><span>TAP HERE</span><i></i><i></i><i></i></div><div class="mini-phone"><span class="speaker"></span><div class="phone-screen"><div class="phone-brand">streetvouch</div><b>How was<br>your visit?</b><span class="tiny-button">Google review</span><span class="tiny-button alt">Private feedback</span></div></div><div class="nfc-waves"><i></i><i></i><i></i></div></div><h3>Customer taps</h3><p>The NFC tag opens the shop’s feedback page instantly.</p></article><article class="story-stage collect-stage"><span class="stage-no">02</span><div class="review-stack"><div class="review-pill p1"><span>★★★★★</span><b>“Great service”</b></div><div class="review-pill p2"><span>★★★★☆</span><b>“Worth the wait”</b></div><div class="review-pill p3"><span>★★★★★</span><b>“Incredible service, best around”</b></div><div class="review-pill p4"><span>✉</span><b>Private feedback</b></div><div class="ai-node">SV</div></div><h3>Feedback gathers</h3><p>Public reviews and private messages are brought together.</p></article><article class="story-stage insight-stage"><span class="stage-no">03</span><div class="mini-report"><div class="mini-report-top"><span>WEEK 24</span><strong>Ready</strong></div><b>Your customer pulse</b><div class="mini-bars"><i style="--h:45%"></i><i style="--h:65%"></i><i style="--h:55%"></i><i style="--h:82%"></i><i style="--h:72%"></i></div><div class="mini-insight"><span>↗</span><small><b>Friendly service</b><br>mentioned 8 times</small></div><div class="mini-alert"><span>!</span><small><b>Watch waiting times</b><br>3 mentions this week</small></div></div><h3>Insight arrives</h3><p>Clear themes show what customers love and what needs attention.</p></article><article class="story-stage handle-stage"><span class="stage-no">04</span><div class="handle-board"><div class="handled-row"><span>★★★★★</span><div><b>Reply sent</b><small>Warm thank-you in your voice</small></div><i>✓</i></div><div class="handled-row"><span>★★★★☆</span><div><b>Reply sent</b><small>Helpful response published</small></div><i>✓</i></div><div class="handled-row alert-row"><span>!</span><div><b>Owner alerted</b><small>Sensitive feedback needs you</small></div><i>→</i></div><div class="handled-total"><b>9 handled</b><span>1 needs attention</span></div></div><h3>Feedback is handled</h3><p>Routine replies are taken care of. Sensitive issues reach the owner.</p></article></div><div class="story-caption"><span><b>0 apps</b> for customers</span><span><b>1 place</b> for every voice</span><span><b>Clear action</b> from every week</span><span><b>Minutes</b> saved every day</span></div></div></section>
<section id="benefits" class="section"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Less admin. More understanding.</div><h2>Good feedback shouldn’t<br>get lost in a busy day.</h2></div><p>Keep a finger on the pulse of your business, without another daily task.</p></div><div class="benefits"><article class="benefit"><span class="symbol" aria-hidden="true">☆</span><h3>Make it easy to speak up.</h3><p>A branded tap-and-scan stand gives every customer a simple choice: leave a Google review or share feedback privately.</p></article><article class="benefit"><span class="symbol" aria-hidden="true">↩</span><h3>Keep the conversation going.</h3><p>Routine positive reviews get thoughtful replies in your voice. Sensitive feedback gets the attention it needs.</p></article><article class="benefit"><span class="symbol" aria-hidden="true">≋</span><h3>See what keeps coming up.</h3><p>Bring reviews and private feedback together. Spot recurring issues, celebrate what’s working and decide what to improve.</p></article></div></div></section>
<section id="how" class="section dark"><div class="wrap"><div class="section-head"><div><div class="eyebrow">A small stand. A useful habit.</div><h2>From your counter<br>to a clearer picture.</h2></div><p>A simple experience for customers. A quieter inbox for you.</p></div><div class="steps"><article class="step"><span class="step-num">01 / INVITE</span><h3>One tap opens the door.</h3><p>Customers tap their phone or scan the QR code. Your branded feedback page opens with no app to download.</p></article><article class="step"><span class="step-num">02 / LISTEN</span><h3>Every voice has a place.</h3><p>Public Google reviews and private comments are reviewed for themes and urgency. Important issues are flagged promptly.</p></article><article class="step"><span class="step-num">03 / UNDERSTAND</span><h3>Your week, made clear.</h3><p>A concise report shows what customers loved, what needs attention and what you can do next.</p></article></div><a class="demo-link" href="/t/JB001/">See what your customers see <span aria-hidden="true">↗</span></a></div></section>
<section class="section"><div class="wrap report-section"><div><div class="eyebrow">The useful part lands in your inbox</div><h2>Less noise.<br>More “now I know.”</h2><p>You shouldn’t have to read every comment to understand your customers. Get the themes that matter in a clear weekly update.</p><ul class="checklist"><li>What customers are loving</li><li>Issues that deserve your attention</li><li>Review responses and feedback activity</li><li>Practical next steps for the week ahead</li></ul><span class="micro">Urgent issues are flagged separately from the weekly report.</span></div><div class="report" aria-label="Illustrative weekly report"><div class="card-top"><span class="brand" style="font-size:18px">${brand}</span><small>SAMPLE REPORT</small></div><h3>Your week, at a glance.</h3><div class="report-stats"><div><b>12</b>new Google reviews</div><div><b>8</b>private comments</div></div><div class="insight"><strong>Customers love the welcome.</strong><p>Friendly service and attention to detail came up most often this week.</p></div><div class="insight" style="background:#f5f0e3"><strong>One thing to look into.</strong><p>Three customers mentioned Saturday waiting times. Review your busiest appointment slots.</p></div><small class="report-note">Example data • Reports and alerts are part of the planned pilot.</small></div></div></section>
<section id="questions" class="section" style="padding-top:20px"><div class="wrap faq-layout"><div><div class="eyebrow">A few things worth knowing</div><h2>Simple for customers.<br>Clear for you.</h2></div><div class="faq-list"><details><summary>Do customers need an app?</summary><p>No. Tapping the NFC stand or scanning the QR code opens a mobile web page. Customers choose how they want to share their experience.</p></details><details><summary>Can everyone leave a Google review?</summary><p>Yes. The public review and private feedback options are available to everyone. We don’t filter customers by their rating or hide the public option after criticism.</p></details><details><summary>Will AI reply to every complaint?</summary><p>No. Automated replies are limited by agreed rules. Serious or unclear complaints need human attention, and business decisions such as refunds remain with the owner.</p></details><details><summary>What is included in the first pilot?</summary><p>The planned 30-day pilot covers a branded NFC/QR stand, customer page, private feedback, review assistance and a weekly report. Scope and permissions are agreed before launch.</p></details><details><summary>Can I try it before speaking to anyone?</summary><p>Absolutely. Open the barber demo and try the private-feedback journey. It uses a fictional business and does not send messages or post reviews.</p><a class="demo-link" style="color:var(--ink);margin-top:15px" href="/t/JB001/">Open the barber demo ↗</a></details></div></div></section>
<section class="wrap"><div class="cta"><div><h2>Your next great customer<br>experience starts with listening.</h2><p>Take the customer journey for a spin.</p></div><a class="btn" href="/t/JB001/">Try the barber demo <span aria-hidden="true">↗</span></a></div></section></main><footer class="footer"><div class="wrap footer-inner"><div><a class="brand" href="/">${brand}</a><br><small>Built for the businesses that make a neighbourhood.</small></div><div class="footer-links"><a href="/t/JB001/">Customer demo</a><button class="back-btn" style="margin:0" id="privacy">Demo privacy</button></div><small>© ${new Date().getFullYear()} StreetVouch</small></div></footer>`;document.getElementById('privacy').onclick=()=>modal('About this demonstration','This preview uses a fictional barber and illustrative reviews. Feedback entered into the demo is not saved or sent. Live customer data, Google integration and messaging will be configured before a real pilot. Photography by Nathon Oski on Unsplash.');}
function barberPage(){document.body.classList.add('barber');app.innerHTML=`<div class="demo-banner">StreetVouch demo · Fictional business · No messages are sent <a href="/">Back to StreetVouch</a></div><main class="barber-layout"><section class="barber-visual" aria-label="Sample barbershop"><img src="${photo}" alt="Classic barber chairs in a warm brick-lined shop" fetchpriority="high"><div class="barber-overlay"><div class="barber-wordmark">THE CORNER BARBER</div><div><h1>A good cut.<br>A proper welcome.</h1><p>The little details matter to us.<br>So does what you think.</p></div><a class="photo-credit" href="https://unsplash.com/photos/black-leather-barber-chair-near-brown-brick-wall-EW_rqoSdDes" target="_blank" rel="noopener">Photography: Nathon Oski / Unsplash</a></div></section><section class="barber-panel" id="journey" aria-live="polite"></section></main>`;choices();}
const powered=`<div class="powered">Feedback made simple with <a class="brand" href="/">${brand}</a></div>`;
function choices(){const el=document.getElementById('journey');el.innerHTML=`<div class="barber-badge" aria-hidden="true">CB</div><div class="eyebrow">Thanks for stopping by</div><h2>How was your visit?</h2><p class="barber-intro">A few words can make a real difference.<br>Share your experience in the way that suits you.</p><button class="choice" id="google"><span class="choice-icon" aria-hidden="true">G</span><span><b>Leave a Google review</b><small>Share your experience publicly on Google</small></span><span class="arrow" aria-hidden="true">↗</span></button><button class="choice" id="private"><span class="choice-icon" aria-hidden="true">✉</span><span><b>Send private feedback</b><small>Share a compliment, concern or suggestion</small></span><span class="arrow" aria-hidden="true">→</span></button><p class="privacy-note">Your choice. All honest feedback is welcome.</p>${powered}`;document.getElementById('google').onclick=()=>modal('This is where Google opens.','For a real shop, this button takes you directly to its Google review form. The Corner Barber is a fictional demo, so no public review can be posted here.');document.getElementById('private').onclick=feedback;}
function feedback(){document.getElementById('journey').innerHTML=`<button class="back-btn" id="back">← Back to your options</button><div class="eyebrow">A note for the team</div><h2>We’re listening.</h2><p class="barber-intro">Tell us what worked, what didn’t, or what would make your next visit better.</p><form class="feedback-form" id="feedback"><label>What’s it about? <span class="micro">Optional</span></label><div class="chips" aria-label="Feedback topic">${['Your haircut','The welcome','Waiting time','Something else'].map(t=>`<button class="chip" type="button" aria-pressed="false">${t}</button>`).join('')}</div><label for="message">Your feedback</label><textarea id="message" name="message" required minlength="3" maxlength="2000" placeholder="Tell us about your experience…"></textarea><div class="field-meta"><span id="count">0</span> / 2,000</div><label for="name">Your name <span class="micro">Optional</span></label><input id="name" name="name" type="text" maxlength="100" placeholder="First name" autocomplete="given-name"><label class="consent"><input id="contact" type="checkbox"><span>I’d like the team to get back to me.</span></label><div id="email-field" hidden><label for="email">Email address</label><input id="email" type="email" autocomplete="email" placeholder="you@example.com"><small class="micro">Used to respond to your feedback, not for marketing.</small></div><button class="btn form-submit" type="submit">Preview sending feedback <span aria-hidden="true">→</span></button><p class="privacy-note">Demo only. Please use sample details.<br>Your message won’t be stored or sent.</p></form>${powered}`;document.getElementById('back').onclick=choices;document.querySelectorAll('.chip').forEach(b=>b.onclick=()=>{document.querySelectorAll('.chip').forEach(x=>x.setAttribute('aria-pressed','false'));b.setAttribute('aria-pressed','true')});document.getElementById('message').oninput=e=>document.getElementById('count').textContent=e.target.value.length;document.getElementById('contact').onchange=e=>{document.getElementById('email-field').hidden=!e.target.checked;document.getElementById('email').required=e.target.checked};document.getElementById('feedback').onsubmit=e=>{e.preventDefault();document.getElementById('journey').innerHTML=`<div class="success-icon" aria-hidden="true">✓</div><div class="eyebrow">Demo complete</div><h2>That’s all it takes.</h2><p class="barber-intro">In the live version, your feedback would now be with the shop’s team. This demo hasn’t saved or sent your message.</p><button class="btn form-submit" id="again">Try the experience again</button><p class="privacy-note">Thanks for trying StreetVouch.</p>${powered}`;document.getElementById('again').onclick=choices;};}
barber?barberPage():home();
if(!barber){const handled=document.querySelector('.handle-stage>p');handled.textContent='Routine reviews receive thoughtful replies, sensitive issues reach the owner, and your public reputation stays active.';const finalCaption=document.querySelector('.story-caption span:last-child');finalCaption.innerHTML='<b>Stronger signals</b> for search and AI';const outcome=document.createElement('div');outcome.className='visibility-outcome';outcome.innerHTML='<span class="visibility-icon" aria-hidden="true">↗</span><div><h3>A stronger reputation becomes better visibility.</h3><p>More genuine reviews, relevant customer language and thoughtful responses give Google and AI assistants clearer signals about what your business does, where it operates and why customers recommend it.</p></div><span class="visibility-tags"><b>Google</b><b>AI discovery</b><b>Local trust</b></span>';document.querySelector('.story-caption').after(outcome);}
if(barber && document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'start_private_feedback_demo',description:'Open the demo private feedback form. Does not submit or save feedback.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('No parameters expected');feedback();return {state:'feedback_form',demo:true};}})).catch(()=>{});}catch{}}
